namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order.Lines);
        if (tier == CustomerTier.Blocked)
            return 0m;

        var amount = ApplyTierDiscount(subtotal, tier);
        amount = ApplyOverride(amount, order.DiscountOverride);
        amount = ApplyVolumeDiscount(amount, subtotal);
        amount = ApplyChannelAdjustment(amount, order.Channel);

        return Math.Max(0m, amount);
    }

    private static decimal CalculateSubtotal(IEnumerable<OrderLine> lines) =>
        lines.Sum(line => line.UnitPrice * line.Quantity);

    private static decimal ApplyTierDiscount(decimal amount, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? amount * 0.95m : amount;

    private static decimal ApplyOverride(decimal amount, decimal? value) =>
        value is > 0m ? amount - value.Value : amount;

    private static decimal ApplyVolumeDiscount(decimal amount, decimal subtotal) =>
        subtotal > 500m ? amount - 10m : amount;

    private static decimal ApplyChannelAdjustment(decimal amount, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Web => amount,
            OrderChannel.Phone => amount + 2m,
            OrderChannel.Marketplace => amount * 1.02m,
            _ => amount,
        };
}
